"""Pure schemas for reference-based geometry tools, usable without Fusion."""
from fusion_cad.design_state import obj, TEXT

SELECTOR = obj({"face_ref": {"type": "string", "description": "Exact user-picked face handle from an attachment or get_selected_faces. Use alone; bound to its original document and component instance."}, "occurrence": {"type": "string", "description": "Exact occurrence full path from inspect_geometry; omit only for root geometry"},
                "body": {"type": "string", "description": "Exact body name within that component"},
                "token": {"type": "string", "description": "Native entity token returned by inspection, with its occurrence context"}})
VECTOR = {"type": "array", "items": {"type": "number"}, "minItems": 3, "maxItems": 3}
POINT = {"type": "array", "items": TEXT, "minItems": 3, "maxItems": 3, "description": "XYZ length expressions in root coordinates, e.g. ['0 in','20 mm','0 in']"}
ANCHOR = {"type": "string", "enum": ["center", "min", "max", "point"], "description": "Bounding-box center/min/max corner, or pointOnFace for a face. These are geometric anchors, not inferred mounting datums."}
SPECS = {
    "inspect_geometry": (False, "Inspect exact occurrences, bodies and paged faces in root coordinates. Returns selectors, bounds, planar normals/cylinder axes and tokens for measuring or placement. No selector lists root bodies and occurrences; an occurrence selector pages through immediate child instances and direct bodies, even for bodyless assembly wrappers; follow returned selectors to a body, then inspect its exact faces. Bounds alone do not identify interfaces.", obj({"entity": SELECTOR, "offset": {"type":"integer","minimum":0}, "limit":{"type":"integer","minimum":1,"maximum":50}})),
    "measure_geometry": (False, "Measure two exact selected entities in root coordinates. minimum is closest-point distance; plane_separation is signed separation along the first planar face normal and requires parallel faces. Returns witness points, units and selectors. A zero minimum distance does not prove no interference.", obj({"a":SELECTOR,"b":SELECTOR,"mode":{"type":"string","enum":["minimum","plane_separation"]}}, ["a","b"])),
    "verify_relationship": (False, "Check only the specified geometric relation between exact entities. distance/minimum_clearance use closest distance; plane_distance/coplanar use parallel planes; parallel uses unsigned normal angle. Reports measured value, tolerance and passed; does not certify design intent or interference freedom.", obj({"a":SELECTOR,"b":SELECTOR,"relation":{"type":"string","enum":["distance","minimum_clearance","plane_distance","parallel","coplanar"]},"expected":TEXT,"tolerance":TEXT}, ["a","b","relation"])),
    "place_component": (True, "Move or copy a top-level component so an explicit anchor reaches a root-frame point or another entity's anchor plus offset. Optional rotation about a world axis. Returns measured anchor error and transform. Requires release_grounding=true to unground an existing component; refuses joined/rigid-group moves. Copies are created ungrounded. Creates a placement snapshot, not an associative joint. Copy instances share component geometry.", obj({"occurrence":TEXT,"anchor":SELECTOR,"anchor_point":ANCHOR,"target":SELECTOR,"target_point":ANCHOR,"position":POINT,"offset":POINT,"rotation_axis":VECTOR,"rotation_degrees":{"type":"number","minimum":-360,"maximum":360},"copy":{"type":"boolean"},"release_grounding":{"type":"boolean","description":"Explicitly release grounding for this requested placement. Default false. Does not remove joints or rigid groups."}},["occurrence","anchor"])),
    "extrude_between_faces": (True, "Create a new body using a selected planar face as its exact cross-section and another parallel face as native To Entity extent. Preserves face holes. Requires distinct parallel planes; no guessed length. This is a face-section extrusion, not a general tube/frame generator. Returns native feature/dependency tokens and actual extent.", obj({"start":SELECTOR,"end":SELECTOR,"name":TEXT},["start","end"])),
}

